tree = {
    "A": ("B", "C"),
    "B": ("D", "E"),
    "C": (None, None),
    "D": (None, None),
    "E": (None, None)
}

def walk(node, order, result):
    if node is None:
        return
    left, right = tree[node]
    if order == "pre":
        result.append(node)
    walk(left, order, result)
    if order == "in":
        result.append(node)
    walk(right, order, result)
    if order == "post":
        result.append(node)

for order in ["pre", "in", "post"]:
    result = []
    walk("A", order, result)
    print(order, result)

def preorder_iterative(tree, root):
    if root is None:
        return []
    result = []
    stack = [root]
    while stack:
        node = stack.pop()
        result.append(node)
        left, right = tree[node]
        if right is not None:
            stack.append(right)
        if left is not None:
            stack.append(left)
    return result

tree = {"A": ("B", "C"), "B": (None, "D"), "C": (None, None), "D": (None, None)}

print(preorder_iterative(tree, "A"))
print(preorder_iterative(tree, "B"))
print(preorder_iterative({}, None))
